function patternFloydsTriangle(n) {
  let rows = [];
  let val = 1;
  for (let i = 1; i <= n; i++) {
    let row = '';
    for (let j = 1; j <= i; j++) {
      row += val + (j === i ? '' : ' ');
      val++;
    }
    rows.push(row);
  }
  return rows.join('\n');
}

