function patternFloydsTriangle(n) {
  let rows = [];
  let val = 1;
  for (let i = 1; i <= n; i++) {
    let row = [];
    for (let j = 1; j <= i; j++) {
      row.push(val++);
    }
    rows.push(row.join(' '));
  }
  return rows.join('\n');
}
